package glitch

import data.glitch_lib

sensitive_patterns = [
    "password", "secret", "api_key", "apikey", "token", "access_key", "accesskey",
    "secret_key", "secretkey", "admin_password", "master_password", "client_secret",
    "private_key", "credential", "auth", "pwd", "passwd", "secret_id"
]

matches_sensitive(str) = true {
    some pattern in sensitive_patterns
    regex.match(sprintf("(?i).*%s.*", [pattern]), str)
}

is_static(v) {
    v.ir_type in {"String", "Integer", "Float", "Boolean", "Complex"}
} else {
    v.ir_type == "Array"
    every elem in v.value {
        is_static(elem)
    }
} else {
    v.ir_type == "Hash"
    every key, value in v.value {
        is_static(key)
        is_static(value)
    }
}

has_sensitive_static(expr) {
    walk(expr, [path, leaf])
    leaf.ir_type in {"String", "Integer", "Float", "Boolean", "Complex"}
    some i
    i < count(path)
    i >= 0
    key = path[i]
    is_string(key)
    matches_sensitive(key)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attr := glitch_lib.all_attributes(parent)[_]
    matches_sensitive(attr.name)
    is_static(attr.value)
    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Hard-coded credential in attribute - The attribute contains a static value in a sensitive field. (CWE-798)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    var := glitch_lib.all_variables(parent)[_]
    matches_sensitive(var.name)
